//! What `DESCRIBE FUNCTION [EXTENDED]` prints for a Spark built-in function
//! (`vendored/spark-function-descriptions.tsv`, generated by
//! `tests/scripts/gen_function_descriptions.py` from a Spark 4.2.0 run): its rows as Spark
//! prints them, so the text is Spark's own, not a rewrite.

use std::collections::HashMap;
use std::sync::LazyLock;

/// The vendored rows: `name<TAB>row<TAB>row...`, one `#` header line.
const TSV: &str = include_str!("../../vendored/spark-function-descriptions.tsv");

/// The rows of every described function, parsed once.
static ROWS: LazyLock<HashMap<&'static str, Vec<String>>> = LazyLock::new(|| {
    TSV.lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .filter_map(|l| {
            let mut cols = l.split('\t');
            let name = cols.next()?;
            Some((name, cols.map(unescape).collect()))
        })
        .collect()
});

/// Undo the generator's escaping of `\`, a line feed and a tab.
fn unescape(row: &str) -> String {
    let mut out = String::with_capacity(row.len());
    let mut chars = row.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some(other) => out.push(other),
            None => out.push('\\'),
        }
    }
    out
}

/// The `DESCRIBE FUNCTION EXTENDED` rows of the built-in `name` (lower case): `Function:`, `Class:`
/// (not for a parser-level operator), `Usage:` and, when the function has examples or arguments,
/// `Extended Usage:`. `None` for a name Spark 4.2.0 does not have.
#[must_use]
pub fn spark_function_description(name: &str) -> Option<&'static [String]> {
    ROWS.get(name).map(Vec::as_slice)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rows_are_spark_s_with_the_escapes_undone() {
        let abs = spark_function_description("abs").unwrap();
        assert_eq!(abs[0], "Function: abs");
        assert_eq!(
            abs[1],
            "Class: org.apache.spark.sql.catalyst.expressions.Abs"
        );
        assert!(abs[2].starts_with("Usage: abs(expr) - "));
        assert!(abs[3].starts_with("Extended Usage:\n"));
        assert!(abs[3].contains("\n      > SELECT abs(-1);\n"));
        assert!(spark_function_description("no_such_function").is_none());
    }

    #[test]
    fn every_catalog_name_of_4_2_is_described() {
        // 588 catalog names, 14 of them added in 4.3.
        assert!(ROWS.len() >= 570);
        assert!(
            ROWS.values()
                .all(|r| r.len() >= 3 && r[0].starts_with("Function: "))
        );
    }
}
